INSERT INTO "unidad" ("created_at", "updated_at", "deleted_at", "id", "codigo", "sigla", "nombre", "parent_id", "tipo_unidad_id", "tipo_id", "nivel_id", "relacion_id", "oficial", "objetivo", "base_legal", "res_creacion", "fec_creacion", "created_by", "updated_by", "es_troncal", "lado") VALUES ('2026-08-27T16:08:47.949Z', '2026-09-07T14:47:58.832Z', NULL, E'276', E'1.1.0.0.0.0.0.25.1.11.0.0.0.2', E'1.1.0.0.0.0.0.25.1.11.0.0.0.2', E'FCPN-INST-ESTACIÓN EXPERIMENTAL DE RAYOS CÓSMICOS ALPACA', NULL, 31, 2, 3, 1, TRUE, E'CONTRIBUIR AL ESTUDIO Y COMPRENSIÓN DE LOS RAYOS CÓSMICOS Y FENÓMENOS ASTROFÍSICOS DE ALTA ENERGÍA A TRAVÉS DE LA DETECCIÓN, ANÁLISIS Y MODELADO DE PARTÍCULAS CÓSMICAS. LA ESTACIÓN BUSCA AVANZAR EN LA INVESTIGACIÓN CIENTÍFICA MEDIANTE LA OBSERVACIÓN DE FENÓMENOS COMO LA LLUVIA DE PARTÍCULAS PRODUCIDAS POR RAYOS CÓSMICOS Y LA DETECCIÓN DE NEUTRINOS DE ALTA ENERGÍA, UTILIZANDO TECNOLOGÍAS DE VANGUARDIA Y MÉTODOS EXPERIMENTALES AVANZADOS. ADEMÁS, SE PROPONE FORMAR INVESTIGADORES Y PROFESIONALES ALTAMENTE CAPACITADOS EN FÍSICA DE PARTÍCULAS Y ASTROFÍSICA, FOMENTAR LA COLABORACIÓN CIENTÍFICA NACIONAL E INTERNACIONAL, Y DIVULGAR LOS RESULTADOS DE LA INVESTIGACIÓN PARA AUMENTAR EL CONOCIMIENTO SOBRE EL UNIVERSO EN LA COMUNIDAD ACADÉMICA Y EL PÚBLICO EN GENERAL.', NULL, E'', NULL, NULL, NULL, FALSE, E'AUTOMATICO');
INSERT INTO "unidad" ("created_at", "updated_at", "deleted_at", "id", "codigo", "sigla", "nombre", "parent_id", "tipo_unidad_id", "tipo_id", "nivel_id", "relacion_id", "oficial", "objetivo", "base_legal", "res_creacion", "fec_creacion", "created_by", "updated_by", "es_troncal", "lado") VALUES ('2026-07-28T15:09:49.784Z', '2026-09-07T14:47:58.835Z', NULL, E'108', E'1.1.0.0.0.0.0.70.1.54.63.0.0.0', E'1.1.0.0.0.0.0.70.1.54.63.0.0.0', E'FCEF-CARR-INSTITUTO DE INVESTIGACIÓN Y CAPACITACIÓN EN CIENCIAS ADMINISTRATIVAS', NULL, 29, 2, 3, 1, TRUE, E'GENERAR CONOCIMIENTOS, INNOVACIÓN, TRANSFERENCIA DE TECNOLOGÍAS, A TRAVÉS DE LA INVESTIGACIÓN BÁSICA Y APLICADA; COADYUVAR EN LA FORMACIÓN EN POSGRADO E INTERACCIÓN SOCIAL Y EXTENSIÓN UNIVERSITARIA, QUE CONTRIBUYAN A LA SOLUCIÓN DE LOS PROBLEMAS SOCIALES, ECONÓMICOS Y AMBIENTALES, FORTALECIENDO EL IMPACTO DE LA UMSA A NIVEL NACIONAL E INTERNACIONAL.', NULL, E'HCU 056/93', '1993-04-15', NULL, NULL, FALSE, E'AUTOMATICO');
INSERT INTO "unidad" ("created_at", "updated_at", "deleted_at", "id", "codigo", "sigla", "nombre", "parent_id", "tipo_unidad_id", "tipo_id", "nivel_id", "relacion_id", "oficial", "objetivo", "base_legal", "res_creacion", "fec_creacion", "created_by", "updated_by", "es_troncal", "lado") VALUES ('2026-08-27T14:55:03.006Z', '2026-09-07T14:47:58.842Z', NULL, E'275', E'1.1.0.0.0.0.0.25.1.11.0.0.0.1', E'1.1.0.0.0.0.0.25.1.11.0.0.0.1', E'FCPN-INTS-ESTACIÓN EXPERIMENTAL DE FÍSICA CÓSMICA CHACALTAYA', NULL, 31, 2, 3, 1, TRUE, E'DESARROLLAR INVESTIGACIÓN CIENTÍFICA DE VANGUARDIA EN EL CAMPO DE LA FÍSICA CÓSMICA Y DE ALTAS ENERGÍAS, APROVECHANDO LA UBICACIÓN GEOGRÁFICA PRIVILEGIADA DE LA ESTACIÓN PARA ESTUDIAR RAYOS CÓSMICOS, PARTÍCULAS DE ALTA ENERGÍA Y FENÓMENOS ASTROFÍSICOS. LA ESTACIÓN BUSCA CONTRIBUIR AL AVANCE DEL CONOCIMIENTO CIENTÍFICO A NIVEL GLOBAL, FOMENTAR LA FORMACIÓN DE INVESTIGADORES EN FÍSICA DE PARTÍCULAS Y ASTROFÍSICA, Y PROMOVER LA COLABORACIÓN INTERNACIONAL EN PROYECTOS DE INVESTIGACIÓN. ASIMISMO, SE PROPONE DIVULGAR LOS RESULTADOS CIENTÍFICOS Y SU IMPORTANCIA EN LA COMPRENSIÓN DEL UNIVERSO, TANTO EN LA COMUNIDAD ACADÉMICA COMO EN LA SOCIEDAD EN GENERAL.', NULL, E'', NULL, NULL, NULL, FALSE, E'AUTOMATICO');
INSERT INTO "unidad" ("created_at", "updated_at", "deleted_at", "id", "codigo", "sigla", "nombre", "parent_id", "tipo_unidad_id", "tipo_id", "nivel_id", "relacion_id", "oficial", "objetivo", "base_legal", "res_creacion", "fec_creacion", "created_by", "updated_by", "es_troncal", "lado") VALUES ('2026-08-27T18:35:27.602Z', '2026-09-07T14:47:58.843Z', NULL, E'278', E'1.1.0.0.0.0.0.25.1.11.0.0.0.4', E'1.1.0.0.0.0.0.25.1.11.0.0.0.4', E'FCPN-INST-ESTACIÓN EXPERIMENTAL DE LABORATORIOS GEOMAGNÉTICOS VILLA REMEDIOS', NULL, 31, 2, 3, 1, TRUE, E'REALIZAR INVESTIGACIONES Y MONITOREO DEL CAMPO GEOMAGNÉTICO TERRESTRE Y SUS VARIACIONES, CON EL PROPÓSITO DE ENTENDER LOS PROCESOS GEOFÍSICOS Y SUS INTERACCIONES CON EL ESPACIO EXTERIOR. LA ESTACIÓN SE ENFOCA EN LA RECOLECCIÓN, ANÁLISIS Y DIVULGACIÓN DE DATOS GEOMAGNÉTICOS, CONTRIBUYENDO A LA INVESTIGACIÓN CIENTÍFICA EN ÁREAS COMO LA GEOFÍSICA, LA FÍSICA ESPACIAL Y LA SISMOLOGÍA. ASIMISMO, TIENE COMO OBJETIVO FORMAR Y CAPACITAR A ESTUDIANTES Y PROFESIONALES EN EL CAMPO DEL GEOMAGNETISMO, FOMENTAR COLABORACIONES CON INSTITUCIONES NACIONALES E INTERNACIONALES, Y PROMOVER LA DIFUSIÓN DE CONOCIMIENTOS CIENTÍFICOS SOBRE LA IMPORTANCIA DEL CAMPO GEOMAGNÉTICO Y SU IMPACTO EN LA SOCIEDAD.', NULL, E'', NULL, NULL, NULL, FALSE, E'AUTOMATICO');
