INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-09-07T14:47:59.360Z', '2026-09-07T14:47:59.360Z', NULL, E'910', E'165', 1, E'Preparar y emitir, los estados contables y financieros del  CEPIES, previo análisis y ajustes de cuentas, así como  análisis de consistencia POA Vs. Presupuesto del Área  y Tesorería, en sujeción a la totalidad de disposiciones  normativas vigentes relacionadas, ante ellas, políticas,  lineamientos, circulares, instructivos, normas básicas,  reglamentos específicos, Decretos Supremos vigentes y  otros, para posterior aprobación por el Honorable  Consejo Universitario. ', E'Constitución Política del Estado ');
