INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-09-07T14:47:59.905Z', '2026-09-07T14:47:59.905Z', NULL, E'386', E'141', 31, E'Establecer una estructura de investigación, posgrado, interacción social e innovación con acceso a eficientes sistemas tecnológicos de información y comunicación, oportuna difusión de información de ciencia y tecnología, monitoreo académico científico, eficientes procedimientos administrativos financieros, régimen docente investigador, incentivos, promoción, evaluación, acreditación, normativo y de gestión', NULL);
