INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-09-07T14:48:00.931Z', '2026-09-07T14:48:00.931Z', NULL, E'4947', E'159', 5, E'Gestión de Recaudación y Valores -\tOrganizar y supervisar la recaudación de recursos propios por la venta de valores y recibos universitarios en Cajas del Monoblock Central y la División de Títulos y Diplomas. -\tSupervisar los Movimientos de Ingresos Diarios (MID´s) de las recaudaciones y el movimiento físico de valores universitarios. -\tControlar y supervisar los pedidos de valores e ingresos de valores universitarios. -\tControlar las aperturas de Cargo a los cajeros en cuentas de orden. -\tPrever stock de material para impresión de valores universitarios. -\tGestionar la impresión de valores universitarios en función a los saldos existentes, en cumplimiento a Reglamento Interno de Caja Recaudadora. -\tElaboración de informes trimestrales del movimiento valores universitarios. -\tCoordinar y gestionar con las unidades especializadas la digitalización de valores y recibos universitarios, bajo normas de seguridad. -\tMantener organizada la información operativa de la unidad, conforme a los procedimientos establecid', E'Los Reglamentos Específicos de Tesorería y Crédito Público.');
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-09-07T14:48:00.932Z', '2026-09-07T14:48:00.932Z', NULL, E'5014', E'303', 1, E'Diseñar, rediseñar, actualizar y mejorar el plan de estudios de la carrera, alineado con las necesidades del mercado y los estándares académicos nacionales e internacionales.', NULL);
