INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-09-07T14:48:01.201Z', '2026-09-07T14:48:01.201Z', NULL, E'1123', E'178', 12, E'Expedir criterios legales para el inicio de procesos  disciplinarios internos universitarios y/o administrativos,  conforme a normativa universitaria y disposiciones legales  vigentes. ', E'Decretos que regulan  los Sistemas: SOA,  SPO, SP, SABS, SCI y  SCG.');
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-09-07T14:48:01.202Z', '2026-09-07T14:48:01.202Z', NULL, E'1127', E'178', 13, E'Gestionar la regularización del derecho propietario de  inmuebles de la UMSA, incluyendo las exenciones  impositivas, llevando un registro actualizado de las  propiedades, además de la guarda y custodia de los  documentos de propiedad. ', E'Normativa del Sistema  Universitario  Boliviano.  Estatuto Orgánico de  la UMSA  Art. 4. Principios I. Son  principales de la UMSA:   a) La Autonomía  universitaria. ');
